-- Frozen schema from Monline v1.3.0; used to exercise real upgrade compatibility.
-- Source: https://github.com/caglaryalcin/Monline/blob/v1.3.0/apps/backend/src/schema.json

CREATE TABLE "users" ("id" TEXT PRIMARY KEY NOT NULL, "password" TEXT NOT NULL DEFAULT '', "email" TEXT NOT NULL DEFAULT '', "emailVisibility" INTEGER NOT NULL DEFAULT 0, "verified" INTEGER NOT NULL DEFAULT 0, "name" TEXT NOT NULL DEFAULT '', "avatar" TEXT NOT NULL DEFAULT '', "created" TEXT NOT NULL DEFAULT '', "updated" TEXT NOT NULL DEFAULT '', "language" TEXT NOT NULL DEFAULT '', "dark_theme" INTEGER NOT NULL DEFAULT 0, "display_currency" TEXT NOT NULL DEFAULT '', "totp_secret" TEXT NOT NULL DEFAULT '', "custom_css" TEXT NOT NULL DEFAULT '', "global_currency_prefix" TEXT NOT NULL DEFAULT '', "convert_currency" INTEGER NOT NULL DEFAULT 0, "monthly_budget" REAL NOT NULL DEFAULT 0, "show_logo_on_card" INTEGER NOT NULL DEFAULT 0, "show_price_on_card" INTEGER NOT NULL DEFAULT 0, "show_cycle_on_card" INTEGER NOT NULL DEFAULT 0, "show_payment_method_on_card" INTEGER NOT NULL DEFAULT 0, "show_category_on_card" INTEGER NOT NULL DEFAULT 0, "show_payer_on_card" INTEGER NOT NULL DEFAULT 0, "show_next_payment_on_card" INTEGER NOT NULL DEFAULT 0, "sort_order" TEXT NOT NULL DEFAULT '', "sort_direction" TEXT NOT NULL DEFAULT '', "calendar_view" TEXT NOT NULL DEFAULT '', "main_currency" TEXT NOT NULL DEFAULT '', "monthly_price" INTEGER NOT NULL DEFAULT 0, "show_original_price" INTEGER NOT NULL DEFAULT 0, "hide_disabled" INTEGER NOT NULL DEFAULT 0, "disabled_to_bottom" INTEGER NOT NULL DEFAULT 0, "subscription_progress" INTEGER NOT NULL DEFAULT 0, "mobile_navigation" INTEGER NOT NULL DEFAULT 0, "remove_background" INTEGER NOT NULL DEFAULT 0, "totp_enabled" INTEGER NOT NULL DEFAULT 0, "budget" REAL NOT NULL DEFAULT 0, "dark_theme_mode" REAL NOT NULL DEFAULT 0, "totp_backup_codes" TEXT NOT NULL DEFAULT '', "color_theme" TEXT NOT NULL DEFAULT '', "payment_tracking" INTEGER NOT NULL DEFAULT 0, "totp_configured" INTEGER NOT NULL DEFAULT 0, "totp_login_challenge_hash" TEXT NOT NULL DEFAULT '', "totp_login_challenge_expires" TEXT NOT NULL DEFAULT '', "oidc_subject" TEXT NOT NULL DEFAULT '');

CREATE TABLE "cycles" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '');

CREATE TABLE "exchange_log" ("id" TEXT PRIMARY KEY NOT NULL, "last_update" TEXT NOT NULL DEFAULT '', "provider" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT '');

CREATE TABLE "admin_settings" ("id" TEXT PRIMARY KEY NOT NULL, "open_registrations" INTEGER NOT NULL DEFAULT 0, "disable_login" INTEGER NOT NULL DEFAULT 0, "update_notification" INTEGER NOT NULL DEFAULT 0, "latest_version" TEXT NOT NULL DEFAULT '', "oidc_display_name" TEXT NOT NULL DEFAULT '', "oidc_client_id" TEXT NOT NULL DEFAULT '', "oidc_client_secret" TEXT NOT NULL DEFAULT '', "oidc_issuer_url" TEXT NOT NULL DEFAULT '', "oidc_redirect_uri" TEXT NOT NULL DEFAULT '', "oidc_scopes" TEXT NOT NULL DEFAULT '', "smtp_host" TEXT NOT NULL DEFAULT '', "smtp_port" REAL NOT NULL DEFAULT 0, "smtp_user" TEXT NOT NULL DEFAULT '', "smtp_pass" TEXT NOT NULL DEFAULT '', "smtp_email" TEXT NOT NULL DEFAULT '', "smtp_from_name" TEXT NOT NULL DEFAULT '', "smtp_encryption" TEXT NOT NULL DEFAULT '', "smtp_enabled" INTEGER NOT NULL DEFAULT 0, "max_users" REAL NOT NULL DEFAULT 0, "require_email_validation" INTEGER NOT NULL DEFAULT 0, "server_url" TEXT NOT NULL DEFAULT '', "oidc_enabled" INTEGER NOT NULL DEFAULT 0, "oidc_provider_name" TEXT NOT NULL DEFAULT '', "oidc_redirect_url" TEXT NOT NULL DEFAULT '');

CREATE TABLE "currencies" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "symbol" TEXT NOT NULL DEFAULT '', "code" TEXT NOT NULL DEFAULT '', "rate" REAL NOT NULL DEFAULT 0, "is_main" INTEGER NOT NULL DEFAULT 0, "user" TEXT NOT NULL DEFAULT '');

CREATE TABLE "household" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "is_main" INTEGER NOT NULL DEFAULT 0);

CREATE TABLE "categories" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "order" REAL NOT NULL DEFAULT 0, "color" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "translation_key" TEXT NOT NULL DEFAULT '');

CREATE TABLE "payment_methods" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "icon" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "order" REAL NOT NULL DEFAULT 0, "is_main" INTEGER NOT NULL DEFAULT 0);

CREATE TABLE "frequencies" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "value" REAL NOT NULL DEFAULT 0, "cycle" TEXT NOT NULL DEFAULT '');

CREATE TABLE "subscriptions" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "price" REAL NOT NULL DEFAULT 0, "frequency" REAL NOT NULL DEFAULT 0, "next_payment" TEXT NOT NULL DEFAULT '', "auto_renew" INTEGER NOT NULL DEFAULT 0, "start_date" TEXT NOT NULL DEFAULT '', "notes" TEXT NOT NULL DEFAULT '', "url" TEXT NOT NULL DEFAULT '', "notify" INTEGER NOT NULL DEFAULT 0, "notify_days_before" REAL NOT NULL DEFAULT 0, "inactive" INTEGER NOT NULL DEFAULT 0, "cancellation_date" TEXT NOT NULL DEFAULT '', "logo" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "currency" TEXT NOT NULL DEFAULT '', "cycle" TEXT NOT NULL DEFAULT '', "payment_method" TEXT NOT NULL DEFAULT '', "payer" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL DEFAULT '', "replacement_subscription" TEXT NOT NULL DEFAULT '', "auto_mark_paid" INTEGER NOT NULL DEFAULT 0, "record_type" TEXT NOT NULL DEFAULT '', "end_date" TEXT NOT NULL DEFAULT '', "payment_limit" REAL NOT NULL DEFAULT 0, "payments_completed" REAL NOT NULL DEFAULT 0, "statement_imported" INTEGER NOT NULL DEFAULT 0, "billing_anchor_day" REAL NOT NULL DEFAULT 0, "calendar_history_recovery_passes" REAL NOT NULL DEFAULT 0, "calendar_projection_hidden" INTEGER NOT NULL DEFAULT 0);

CREATE TABLE "notifications_config" ("id" TEXT PRIMARY KEY NOT NULL, "email_enabled" INTEGER NOT NULL DEFAULT 0, "email_to" TEXT NOT NULL DEFAULT '', "discord_enabled" INTEGER NOT NULL DEFAULT 0, "discord_webhook_url" TEXT NOT NULL DEFAULT '', "telegram_enabled" INTEGER NOT NULL DEFAULT 0, "telegram_bot_token" TEXT NOT NULL DEFAULT '', "telegram_chat_id" TEXT NOT NULL DEFAULT '', "gotify_enabled" INTEGER NOT NULL DEFAULT 0, "gotify_url" TEXT NOT NULL DEFAULT '', "gotify_token" TEXT NOT NULL DEFAULT '', "pushover_enabled" INTEGER NOT NULL DEFAULT 0, "pushover_user_key" TEXT NOT NULL DEFAULT '', "pushover_api_token" TEXT NOT NULL DEFAULT '', "ntfy_enabled" INTEGER NOT NULL DEFAULT 0, "ntfy_url" TEXT NOT NULL DEFAULT '', "ntfy_topic" TEXT NOT NULL DEFAULT '', "ntfy_username" TEXT NOT NULL DEFAULT '', "ntfy_password" TEXT NOT NULL DEFAULT '', "ntfy_auth_token" TEXT NOT NULL DEFAULT '', "pushplus_enabled" INTEGER NOT NULL DEFAULT 0, "pushplus_token" TEXT NOT NULL DEFAULT '', "mattermost_enabled" INTEGER NOT NULL DEFAULT 0, "mattermost_webhook_url" TEXT NOT NULL DEFAULT '', "webhook_enabled" INTEGER NOT NULL DEFAULT 0, "webhook_url" TEXT NOT NULL DEFAULT '', "serverchan_enabled" INTEGER NOT NULL DEFAULT 0, "serverchan_send_key" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "reminders" TEXT DEFAULT 'null');

CREATE TABLE "fixer_settings" ("id" TEXT PRIMARY KEY NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 0, "api_key" TEXT NOT NULL DEFAULT '', "provider" TEXT NOT NULL DEFAULT '', "base_currency" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "api_key_configured" INTEGER NOT NULL DEFAULT 0);

CREATE TABLE "yearly_costs" ("id" TEXT PRIMARY KEY NOT NULL, "year" REAL NOT NULL DEFAULT 0, "month" REAL NOT NULL DEFAULT 0, "total" REAL NOT NULL DEFAULT 0, "user" TEXT NOT NULL DEFAULT '');

CREATE TABLE "notification_log" ("id" TEXT PRIMARY KEY NOT NULL, "subscription_id" TEXT NOT NULL DEFAULT '', "user_id" TEXT NOT NULL DEFAULT '', "reminder_key" TEXT NOT NULL DEFAULT '', "sent_date" TEXT NOT NULL DEFAULT '');

CREATE TABLE "payment_records" ("id" TEXT PRIMARY KEY NOT NULL, "user" TEXT NOT NULL DEFAULT '', "subscription_id" TEXT NOT NULL DEFAULT '', "due_date" TEXT NOT NULL DEFAULT '', "paid_at" TEXT NOT NULL DEFAULT '', "auto_paid" INTEGER NOT NULL DEFAULT 0, "amount" REAL NOT NULL DEFAULT 0, "notes" TEXT NOT NULL DEFAULT '', "proof" TEXT NOT NULL DEFAULT '', "statement_sources" TEXT DEFAULT 'null', "name" TEXT NOT NULL DEFAULT '', "currency" TEXT NOT NULL DEFAULT '', "logo" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL DEFAULT '', "payment_method" TEXT NOT NULL DEFAULT '', "payer" TEXT NOT NULL DEFAULT '', "scheduled_date" TEXT NOT NULL DEFAULT '');

CREATE TABLE "api_keys" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL DEFAULT '', "key_hash" TEXT NOT NULL DEFAULT '', "key_prefix" TEXT NOT NULL DEFAULT '', "permissions" TEXT NOT NULL DEFAULT '', "last_used_at" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '', "created_at" TEXT NOT NULL DEFAULT '');

CREATE TABLE "subscription_history" ("id" TEXT PRIMARY KEY NOT NULL, "subscription_id" TEXT NOT NULL DEFAULT '', "event_type" TEXT NOT NULL DEFAULT '', "effective_date" TEXT NOT NULL DEFAULT '', "old_price" REAL NOT NULL DEFAULT 0, "new_price" REAL NOT NULL DEFAULT 0, "old_cycle" TEXT NOT NULL DEFAULT '', "new_cycle" TEXT NOT NULL DEFAULT '', "old_frequency" REAL NOT NULL DEFAULT 0, "new_frequency" REAL NOT NULL DEFAULT 0, "old_currency" TEXT NOT NULL DEFAULT '', "new_currency" TEXT NOT NULL DEFAULT '', "note" TEXT NOT NULL DEFAULT '', "created" TEXT NOT NULL DEFAULT '', "user" TEXT NOT NULL DEFAULT '');

CREATE TABLE "bank_statements" ("id" TEXT PRIMARY KEY NOT NULL, "user" TEXT NOT NULL DEFAULT '', "bank" TEXT NOT NULL DEFAULT '', "file_name" TEXT NOT NULL DEFAULT '', "file_hash" TEXT NOT NULL DEFAULT '', "period" TEXT NOT NULL DEFAULT '', "page_count" REAL NOT NULL DEFAULT 0, "transactions" TEXT DEFAULT 'null', "created" TEXT NOT NULL DEFAULT '');

CREATE TABLE monline_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE monline_sessions (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires INTEGER NOT NULL, purpose TEXT NOT NULL DEFAULT 'session', remember INTEGER NOT NULL DEFAULT 0);
